import csv
import io
import re


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    old_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(max(old_limit, len(raw_csv)))
        records = list(csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"'))
    finally:
        csv.field_size_limit(old_limit)

    if not records:
        return {"columns": [], "rows": []}

    numeric = re.compile(
        r"^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$"
    )
    first = records[0]
    first_is_data = bool(first) and all(
        numeric.fullmatch(value.strip()) for value in first
    )

    if first_is_data:
        header = []
        rows = records
    else:
        header = first
        rows = records[1:]

    width = max([len(header)] + [len(row) for row in rows])
    columns = []
    used = set()
    for index in range(width):
        name = header[index] if index < len(header) else ""
        if not name:
            name = f"column_{index + 1}"
        base = name
        suffix = 2
        while name in used:
            name = f"{base}_{suffix}"
            suffix += 1
        used.add(name)
        columns.append(name)

    return {
        "columns": columns,
        "rows": [row + [""] * (width - len(row)) for row in rows],
    }
